fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to its integer index in the week,
    // where Sunday is 0, Monday is 1, ..., Saturday is 6.
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day abbreviation"),
    };

    // Calculate days until next Sunday.
    // If today is Sunday (0), days until next Sunday is 7.
    if day_index == 0 {
        7
    } else {
        // For other days: days until Sunday = 7 - current day index
        7 - day_index
    }
}